{
  "runThesis": "Will her earnest presence survive the tests his armored magnetism demands, or will the ruin beneath claim them both?",
  "thematicDirection": "Beauty as armor meets genuine wanting in a world where every bond is a question that must be answered in blood and light.",
  "visualThesis": "from interrupted thresholds and armored reflections to earned convergence where light fractures the ruin instead of hiding it",
  "worldPhysics": "magic makes emotional exposure literal and visible",
  "hiddenPressure": "authenticity is the only currency that cannot be faked",
  "socialGeometry": "solitude is the default armor; intimacy is the dangerous exception",
  "permittedAnomalyStyle": "normalized abnormality — the world never flags the fractures, only the reader feels them",
  "issueArcs": [
    {
      "issueLabel": "Issue 1 — proximity orbit",
      "thesis": "Close orbit forces recognition and entanglement as his tests begin to measure her reality, until severance splits the shared stake.",
      "ambiguityTargets": ["whether his questions are armor or invitation", "if her earnestness passes the test or merely survives it"],
      "pressureVectors": ["his magnetism drawing her into complicity", "magic making every glance a potential revelation"],
      "endingShape": "rupture-and-pursuit",
      "regimePhase": "instability",
      "cliffShape": {
        "preferredFamilies": ["forced_separation", "loyalty_test"],
        "avoidFamilies": ["external_shock"],
        "escalation": "soft proximity and almost-confession early to hard severance at the boundary"
      },
      "visualArc": {
        "tendencies": ["interrupted eye contact across barriers", "armored silhouettes dominating frame"],
        "escalation": ["visual isolation sharpens scene to scene"],
        "withhold": ["centered couple composition until the final rupture"]
      }
    },
    {
      "issueLabel": "Issue 2 — divergence convergence",
      "thesis": "Separate tracks deepen dependency while the gap tests what each became, until forced reunion demands the cost of entanglement be paid.",
      "ambiguityTargets": ["whether the changes apart strengthened or poisoned the bond", "if his final test is protection or self-sabotage"],
      "pressureVectors": ["longing warping under magical exposure", "reliance becoming dangerous to admit"],
      "endingShape": "unresolved gravity",
      "regimePhase": "completion",
      "cliffShape": {
        "preferredFamilies": ["irrevocable_choice", "proximity"],
        "avoidFamilies": ["a_plot_reversal"],
        "escalation": "quiet divergence pressure to charged reunion threshold"
      },
      "visualArc": {
        "tendencies": ["split compositions and parallel reflections", "fading barriers between frames"],
        "escalation": ["light piercing armor increases across scenes"],
        "withhold": ["warm shared lighting until the convergence scene"]
      }
    }
  ],
  "motifBank": ["cracked mirror held between them", "fading sigil on skin", "test delivered in velvet voice", "thread of light pulling through ruin"],
  "voiceAnchors": {
    "li_register": "questions wrapped in velvet command that watch for fracture",
    "pc_register": "earnest interior that leaks through every crack despite the armor"
  },
  "characterIcebergs": {
    "the LI": ["surface: magnetic beauty that arrives carrying a test", "deeper: ruin born from past mirrors that shattered", "deepest: terror that real wanting will finish what the ruin began"]
  },
  "forbiddenDefaults": ["beauty without tests", "instant unguarded trust", "magic as decorative backdrop", "earnestness as weakness", "ruin resolved by love alone"]
}
